"""Data, part B: message brokers and streams, search, analytical databases, object storage, storage arrays and software-defined storage, backup, data integration.

Provider-only services are `saas` kinds (the provider's SLA decides). Self-hosted products say what survives the loss of a node, a controller and a site;
arrays and file systems name the arbiter (witness, tiebreaker, quorum server) that automatic switchover between sites needs."""
from forge import *

FUNCTIONS = {"data": [
    ("storage-array", "Системы хранения (СХД и NAS)", "Storage arrays and NAS", "hard-drive"),
    ("data-integration", "Интеграция и репликация данных", "Data integration and CDC", "refresh-cw"),
]}
IAC = {"storage-array": "appliance", "data-integration": "platform"}

ENC_ON = lambda: boolean("encryptionAtRest", "Шифрование на диске", "Encryption at rest", group="security", default=True)  # a service that always encrypts
S3 = lambda: [dict(p) for p in BACKUP_PROPS if p["key"] in ("bucket", "endpoint")]                                         # bucket / endpoint of an S3 target (database IaC)
BP = lambda: [p for p in backup_props() if p["key"] not in ("vcpu", "ramGb", "diskGb")]                                    # immutability, retention, restore test – no sizing
ROLES = lambda p, r, w=None: [{"id": "primary", "name": L(*p)}, {"id": "replica", "name": L(*r)}] + ([{"id": "witness", "name": L(*w)}] if w else [])  # roles with names in both languages
K8S = {"hosting": "kubernetes"}
DERIVED_SEARCH = ["datastore", "stateful", "search"]   # a provider’s search index is rebuilt from the source of truth: no backup requirement
TOOL = T["platform"] + ["backup-tool"]
DI = T["platform"] + ["data-integration"]

